void check_native_replay() {
  NativeOracleFixture fixture;
  const std::vector<double> a{4.0 / 3.0, 4.0 / 3.0}, b{0, 0}, y{-1.0 / 3.0, -1.0 / 3.0};
  auto& oracle = *fixture.oracle;
  require(oracle.evaluate(fixture.reduced, a, y, 2) == candidate::OracleDecision::accept && oracle.candidate,
      "同一非空恢复栈的首个A点须通过原模型终验");
  const auto owned_a = *oracle.candidate;
  require(oracle.evaluate(fixture.reduced, b, y, 3) == candidate::OracleDecision::reject && oracle.candidate &&
      oracle.candidate->x != owned_a.x && !quality_ok(oracle.candidate->checked),
      "同一Highs实例第二次B恢复须实际改变原坐标点并保真实拒绝质量");
  require(same_vector(owned_a.x, {3, a[0], a[1]}) && quality_ok(owned_a.checked),
      "首个A拥有的向量不能被原生解缓存的后续恢复覆盖");
  require(oracle.evaluate(fixture.reduced, a, y, 4) == candidate::OracleDecision::accept && oracle.candidate &&
      same_vector(oracle.candidate->x, owned_a.x) && same_vector(oracle.candidate->y, owned_a.y) &&
      same_verification(oracle.candidate->checked.primal, owned_a.checked.primal) &&
      same_optimality(oracle.candidate->checked.optimality, owned_a.checked.optimality),
      "同一presolve栈A→B→A须恢复相同数值与完整原质量，不能复用末次缓存冒充");
  require(fixture.stats.oracle.events.size() == 3 && fixture.stats.oracle.started == 3 && fixture.stats.oracle.completed == 3 &&
      fixture.stats.oracle.accepted == 2 && fixture.stats.oracle.rejected == 1 &&
      fixture.stats.postsolve.completed == 3 && fixture.stats.assessments.completed == 3 &&
      fixture.stats.oracle.candidate_event == 2 && !fixture.stats.oracle.selected_event,
      "非空重放须实际发生三次恢复和原验，局部候选不等于owner已提交");
  fixture.no_native_iterations();
  ++transaction_cases;
  details.push_back({"native_postsolve_replays_A_B_A_without_lp", "transaction"});
}

void check_oracle_failure(bool exception) {
  NativeOracleFixture fixture;
  fixture.error_after_assessment = exception;
  fixture.expire_after_assessment = !exception;
  const std::vector<double> x{4.0 / 3.0, 4.0 / 3.0}, y{-1.0 / 3.0, -1.0 / 3.0};
  const auto decision = fixture.oracle->evaluate(fixture.reduced, x, y, 11);
  const auto expected = exception ? candidate::OracleDecision::error : candidate::OracleDecision::budget;
  require(fixture.injected && decision == expected && fixture.oracle->terminal == expected &&
      !fixture.oracle->candidate && fixture.oracle->current_frame == nullptr &&
      fixture.stats.oracle.started == 1 && fixture.stats.oracle.completed == 1 && fixture.stats.oracle.events.size() == 1,
      "oracle内部预算与异常须不抛穿assess，保终止类型并释放局部frame引用");
  const auto& event = fixture.stats.oracle.events.front();
  require(event.postsolve.started == 1 && event.postsolve.completed == 1 && event.assessments.started == 1 &&
      event.assessments.completed == 1 && event.original_quality && event.original_quality->numerically_optimal &&
      event.budget.checks > 0 && event.budget.loop_units > 0 && event.timings.recovery > 0 && event.timings.verification > 0 &&
      fixture.stats.assessments.completed == 1 && !fixture.stats.oracle.selected_event && !fixture.stats.accepted &&
      std::string(event.decision) == (exception ? "error" : "budget") &&
      (exception ? fixture.stats.oracle.errors : fixture.stats.oracle.budget_failures) == 1,
      "原验已完成后失败可留诊断质量，但不得丢已付工作或伪造owner提交");
  fixture.no_native_iterations();
  if (exception) { ++exception_cases; details.push_back({"oracle_error_preserves_event_work", "exception"}); }
  else { ++budget_cases; details.push_back({"oracle_budget_preserves_event_work", "budget"}); }
}

void check_real_core_oracle_failure(bool exception) {
  NativeOracleFixture fixture;
  fixture.error_after_assessment = exception;
  fixture.expire_after_assessment = !exception;
  solver::SolveResult result;
  {
    candidate::ScopedOracle scope(&*fixture.oracle);
    fixture.stats.center_diag.enabled = true;
    candidate::CenterScope center(&fixture.stats.center_diag);
    ++component_ipm_calls;
    // 真实HSD迭代与factor均执行；仅oracle的Now在原验完成后注入确定性失败。
    // core自身继续使用同一个真实Clock epoch，不伪造求解计时或更换公开预算。
    result = solver::v90_core(fixture.reduced, fixture.options, fixture.start);
  }
  const auto expected = exception ? candidate::OracleDecision::error : candidate::OracleDecision::budget;
  require(fixture.injected && result.status == (exception ? "numerical_error" : "time_limit") &&
      result.backend_status == result.status && fixture.oracle->terminal == expected &&
      result.ipm_iterations && *result.ipm_iterations > 0 && result.ipm_factorizations && *result.ipm_factorizations > 0 &&
      fixture.stats.oracle.started == 1 && fixture.stats.oracle.completed == 1 && fixture.stats.oracle.events.size() == 1,
      "真实assess的budget/error桥接必须由实际HSD core返回既有失败类型，并保已付迭代与factor");
  const auto& event = fixture.stats.oracle.events.front();
  require(event.iteration == result.ipm_iterations && event.postsolve.completed == 1 &&
      event.assessments.completed == 1 && event.original_quality && event.budget.checks > 0 &&
      event.budget.loop_units > 0 && event.timings.recovery > 0 && event.timings.verification > 0 &&
      !fixture.oracle->candidate && !fixture.stats.oracle.selected_event && !fixture.stats.accepted &&
      (exception ? fixture.stats.oracle.errors : fixture.stats.oracle.budget_failures) == 1,
      "真实core异常收口不能抹去oracle事件的恢复、原验与部分成本，也不得提交原候选");
  require(result.solve_seconds >= 0 && result.verification_seconds >= 0 && result.total_seconds >= result.solve_seconds,
      "真实core保自身时钟测量，不把oracle合成时钟写成其耗时证据");
  fixture.no_native_iterations();
  if (exception) { ++exception_cases; details.push_back({"oracle_real_core_error_bridge", "exception"}); }
  else { ++budget_cases; details.push_back({"oracle_real_core_budget_bridge", "budget"}); }
}

void check_center_identity() {
  const std::vector<bool> inequality{true};
  const std::vector<double> s{1}, z{1}, ds{-1}, dz{0};
  // 取零G/c/b的仿射方程：两对互补线性项均为-1，Q=ds*dz+dtau*dkappa=0。
  // 精确HSDE条件下新旧公式应恒等；不把数值反馈表述为遗漏二阶项的修复。
  const long double current_c = 2;
  require(static_cast<long double>(ds[0]) * z[0] + static_cast<long double>(s[0]) * dz[0] == -1 &&
      static_cast<long double>(ds[0]) * dz[0] + 0.0L * -1.0L == 0, "恒等式夹具须满足互补线性式与零Q");
  for (double alpha : {0.0, 0.25, 0.75, 1.0}) {
    candidate::CenterDiagnostics diagnostics;
    diagnostics.enabled = true;
    int checks = 0;
    const double remaining = 1 - alpha;
    const double legacy = remaining * remaining * remaining;
    const double sigma = candidate::predicted_center(inequality, s, z, ds, dz, 1, 1, 0, -1, alpha,
        current_c, legacy, 42, diagnostics, [&] { ++checks; });
    require(sigma == legacy && diagnostics.started == 1 && diagnostics.completed == 1 && diagnostics.last &&
        diagnostics.rows_scanned == 1 && diagnostics.inequality_terms == 1 && diagnostics.budget_checks == checks && checks == 3 &&
        diagnostics.last->iteration == 42 && std::string(diagnostics.last->status) == "completed" &&
        diagnostics.last->affine_c == 2 * remaining && diagnostics.last->ratio == remaining && diagnostics.last->sigma == sigma &&
        diagnostics.last->negative_predictions == 0 && diagnostics.last->scalar_term_complete && !diagnostics.last->sigma_underflow,
        "精确HSDE的预测互补量应与旧步长代理恒等，诊断只计实际扫描和预算检查");
  }
  ++transaction_cases;
  details.push_back({"center_hsde_identity", "transaction"});
}

void check_center_perturbed_prediction() {
  const std::vector<bool> inequality{true};
  const std::vector<double> s{1}, z{1};
  const auto evaluate = [&](double ds, double dz, double dtau, double dkappa, double expected,
      double expected_c, std::int64_t negatives) {
    candidate::CenterDiagnostics diagnostics;
    diagnostics.enabled = true;
    const double sigma = candidate::predicted_center(inequality, s, z, std::vector<double>{ds}, std::vector<double>{dz},
        1, 1, dtau, dkappa, 1, 2.0L, 0, 9, diagnostics, [] {});
    require(sigma == expected && diagnostics.completed == 1 && diagnostics.last &&
        diagnostics.last->affine_c == expected_c && diagnostics.last->negative_predictions == negatives &&
        diagnostics.last->sigma == expected && diagnostics.last->legacy_sigma == 0,
        "有数值偏离的已存方向须按真实互补总和反馈，不能用旧步长代理替代");
  };
  // 这组满足两对互补线性式，但Q非零，不冒称满足完整HSDE仿射系统。
  evaluate(-0.5, -0.5, -0.5, -0.5, 1.0 / 64.0, 0.5, 0);
  // 负预测不逐坐标投影；先合计，再对最终比值做[0,1]截断。
  // 若把负slack先夹到0，第一例会错误得到sigma=1/8。
  evaluate(-2, 0, 0, 0, 0, 0, 1);
  evaluate(-4, 0, 0, 0, 0, -2, 1);
  evaluate(1, 1, 0, 0, 1, 5, 0);
  for (bool bad_dimension : {false, true}) {
    candidate::CenterDiagnostics diagnostics;
    diagnostics.enabled = true;
    const std::vector<double> bad = bad_dimension ? std::vector<double>{} :
        std::vector<double>{std::numeric_limits<double>::quiet_NaN()};
    bool rejected = false;
    try { candidate::predicted_center(inequality, s, z, bad, std::vector<double>{0}, 1, 1, 0, 0, 1,
        2.0L, 0, 9, diagnostics, [] {}); }
    catch (const candidate::CenterError&) { rejected = true; }
    require(rejected && diagnostics.started == 1 && diagnostics.completed == 0 && diagnostics.last &&
        std::string(diagnostics.last->status) == "arithmetic_error", "坏维数或非有限仿射方向应保部分诊断并拒绝，不回退伪成功");
  }
  ++transaction_cases;
  details.push_back({"center_perturbed_prediction", "transaction"});
}

void check_center_equality_only() {
  const auto run = [&](const std::vector<bool>& inequality, const std::vector<double>& s,
      const std::vector<double>& z, const std::vector<double>& ds, const std::vector<double>& dz) {
    candidate::CenterDiagnostics diagnostics;
    diagnostics.enabled = true;
    const auto sigma = candidate::predicted_center(inequality, s, z, ds, dz, 2, 3, -1, 0, 1,
        6.0L, 0, 4, diagnostics, [] {});
    require(sigma == 0.125 && diagnostics.last && diagnostics.last->affine_c == 3 && diagnostics.last->ratio == 0.5 &&
        diagnostics.rows_scanned == static_cast<std::int64_t>(inequality.size()) && diagnostics.inequality_terms == 0 &&
        diagnostics.last->scalar_term_complete && diagnostics.completed == 1,
        "等式不贡献互补乘积，空不等式集仍须使用真实tau/kappa预测项");
  };
  run({}, {}, {}, {}, {});
  // 等式的slack和对偶不在正锥互补项中；这里故意放无关非有限值，证明不误纳入求和。
  const auto nan = std::numeric_limits<double>::quiet_NaN();
  run({false, false}, {-infinity, nan}, {0, infinity}, {nan, nan}, {nan, nan});
  ++transaction_cases;
  details.push_back({"center_equality_only", "transaction"});
}

void check_center_tiny_ratio() {
  const auto tiny = std::ldexp(1.0, -400);
  candidate::CenterDiagnostics diagnostics;
  diagnostics.enabled = true;
  const long double current_c = 1.0L + static_cast<long double>(tiny);
  const auto sigma = candidate::predicted_center(std::vector<bool>{true}, std::vector<double>{1}, std::vector<double>{1},
      std::vector<double>{-1}, std::vector<double>{0}, tiny, 1, 0, 0, 1, current_c, 0, 3, diagnostics, [] {});
  require(sigma == 0 && diagnostics.completed == 1 && diagnostics.last && diagnostics.last->ratio == tiny &&
      diagnostics.last->sigma == 0 && diagnostics.last->sigma_underflow && diagnostics.last->negative_predictions == 0,
      "正比值立方窄化为0是合法中心参数，必须另留underflow诊断，不能据日志窄化值重判LD结果");
  if constexpr (std::numeric_limits<long double>::min_exponent < -1200) {
    const auto small = std::ldexp(1.0, -600);
    const long double product = static_cast<long double>(small) * small;
    candidate::CenterDiagnostics extended;
    extended.enabled = true;
    const auto value = candidate::predicted_center(std::vector<bool>{true}, std::vector<double>{small}, std::vector<double>{small},
        std::vector<double>{-small}, std::vector<double>{0}, small, small, 0, 0, 1, 2 * product, 0, 3, extended, [] {});
    require(value == 0.125 && extended.completed == 1 && extended.last && !extended.last->current_c && !extended.last->affine_c &&
        extended.last->ratio == 0.5 && !extended.last->sigma_underflow,
        "平台有扩展指数时，应先在LD中除C；正C/A窄化成null不能把本来有限的sigma误判为无效");
  }
  ++transaction_cases;
  details.push_back({"center_tiny_ratio", "transaction"});
}

struct CenterBudgetSignal { int ordinal; };

void check_center_budget_transaction() {
  const std::vector<bool> inequality(4097, true);
  const std::vector<double> s(4097, 1), z(4097, 1), ds(4097, 0), dz(4097, 0);
  const std::vector<std::int64_t> scanned{0, 0, 4096, 4097};
  for (int boundary = 1; boundary <= 4; ++boundary) {
    candidate::CenterDiagnostics diagnostics;
    diagnostics.enabled = true;
    int calls = 0;
    double published = -1;
    bool same_exception = false;
    try { published = candidate::predicted_center(inequality, s, z, ds, dz, 1, 1, 0, 0, 0.5,
        4098.0L, 0.125, 14, diagnostics, [&] { if (++calls == boundary) throw CenterBudgetSignal{boundary}; }); }
    catch (const CenterBudgetSignal& failure) { same_exception = failure.ordinal == boundary; }
    require(same_exception && published == -1 && calls == boundary && diagnostics.budget_checks == boundary &&
        diagnostics.started == 1 && diagnostics.completed == 0 && diagnostics.last &&
        diagnostics.rows_scanned == scanned[static_cast<std::size_t>(boundary - 1)] &&
        diagnostics.last->rows_scanned == diagnostics.rows_scanned && diagnostics.inequality_terms == diagnostics.rows_scanned &&
        diagnostics.last->inequality_terms == diagnostics.inequality_terms && std::string(diagnostics.last->status) == "running" &&
        diagnostics.last->scalar_term_complete == (boundary > 1) &&
        (boundary == 4 ? diagnostics.last->sigma == 1 : !diagnostics.last->sigma),
        "每个真实4096批量预算边界都须原样透传异常、保已付扫描；最后预算失败也不得提交sigma");
  }
  candidate::CenterDiagnostics diagnostics;
  diagnostics.enabled = true;
  int calls = 0;
  bool original_error = false;
  try { candidate::predicted_center(inequality, s, z, ds, dz, 1, 1, 0, 0, 0.5, 4098.0L, 0.125, 14, diagnostics,
      [&] { if (++calls == 4) throw std::runtime_error("中心参数原回调异常"); }); }
  catch (const candidate::CenterError&) { original_error = false; }
  catch (const std::runtime_error& failure) { original_error = std::string(failure.what()) == "中心参数原回调异常"; }
  require(original_error && diagnostics.completed == 0 && diagnostics.rows_scanned == 4097 && diagnostics.last &&
      diagnostics.last->sigma == 1, "用户std回调异常不能被包装成CenterError或丢掉已完成但未提交的诊断");
  ++budget_cases;
  details.push_back({"center_budget_transaction", "budget"});
}

void check_center_disabled_scope() {
  const auto model = coupled();
  const auto options = policy();
  const auto expected = real_core(model, options);
  candidate::CenterDiagnostics outer, inner;
  outer.enabled = inner.enabled = true;
  auto* previous = candidate::active_center;
  {
    candidate::CenterScope scope(&outer);
    same_non_timing(real_wrapper(model, options, false), expected);
    auto mip = model;
    mip.kinds[0] = solver::VariableKind::integer;
    const auto bypass = real_wrapper(mip, options, true);
    require(bypass.status == "error" && !bypass.has_solution && candidate::active_center == &outer &&
        outer.started == 0 && outer.completed == 0 && !outer.last,
        "关闭或不支持配置须隔离新中心参数，保父路径且不串用外层诊断");
    try {
      candidate::CenterScope nested(&inner);
      require(candidate::active_center == &inner, "嵌套中心参数scope应指向自己的具名owner");
      throw std::runtime_error("中心参数scope异常");
    } catch (const std::runtime_error&) {}
    require(candidate::active_center == &outer && inner.started == 0, "异常退出须恢复此前中心参数scope，不伪造计算");
  }
  require(candidate::active_center == previous, "新中心参数scope析构不得留下悬空owner指针");
  ++transaction_cases;
  details.push_back({"center_disabled_scope", "transaction"});
}

}  // 匿名命名空间

int main() {
  try {
    check_off_wrapper();
    mapping("minimum_column_lower_offset", scalar(2, 1, 4, 7), 9, true);
    mapping("minimum_column_upper_offset", scalar(-2, -5, -2, -3), 1, true);
    mapping("maximum_column_upper_offset", scalar(3, -1, 4, 7, true), 19, true);
    auto model = scalar(3, -infinity, infinity, -4); row(model, 2, 4, infinity);
    mapping("minimum_original_row_lower", model, 2, true);
    model = scalar(2, -infinity, infinity, 7, true); row(model, 1, -infinity, 3);
    mapping("maximum_original_row_upper", model, 13, true);
    model = scalar(3, -5, 8); row(model, 1, 2, 5);
    mapping("ranged_row_lower", model, 6, true);
    model.sense = solver::ObjectiveSense::maximize;
    mapping("ranged_row_upper", model, 15, true);
    model = scalar(7, 3, 3, 11);
    model.costs.push_back(3); model.column_lower.push_back(-infinity); model.column_upper.push_back(infinity);
    model.kinds.push_back(solver::VariableKind::continuous); model.row_lower = {19}; model.row_upper = {19};
    model.column_start = {0, 1, 2}; model.row_index = {0, 0}; model.values = {5, 2};
    mapping("fixed_column_equality_offset", model, 38, true);
    mapping("minimum_real_reduced_child", coupled(true), 88.0 / 3.0, false);
    mapping("maximum_real_reduced_child", coupled(true, true), 104.0 / 3.0, false);
    check_not_reduced(); check_mip_bypass(); check_zero_budget(false); check_zero_budget(true);
    check_quality_transaction(); check_commit(true); check_commit(false);
    for (const auto kind : {ChildKind::good_nonoptimal, ChildKind::bad_dual, ChildKind::bad_primal,
                           ChildKind::no_candidate, ChildKind::bad_dimension}) synthetic_child(kind);
    check_presolve_status(); check_entry_deadline();
    check_late_boundary(true, false); check_late_boundary(false, false); check_late_boundary(false, true);
    check_child_exception(true); check_child_exception(false);
    for (const auto kind : {ProjectionKind::raw_pass, ProjectionKind::unchanged, ProjectionKind::dual_lower,
                           ProjectionKind::dual_upper, ProjectionKind::primal_lower, ProjectionKind::primal_upper,
                           ProjectionKind::both, ProjectionKind::breaks_row, ProjectionKind::breaks_gap,
                           ProjectionKind::nonfinite}) check_projection(kind);
    for (const auto boundary : {ProjectionBoundary::copy, ProjectionBoundary::primal, ProjectionBoundary::dual_after,
                               ProjectionBoundary::scan, ProjectionBoundary::trial_assessment, ProjectionBoundary::commit,
                               ProjectionBoundary::ordinary_then_expired}) check_projection_budget(boundary);
    check_projection_exception(false); check_projection_exception(true);
    check_old_incumbent_hook(); check_reject_then_accept_hook(); check_oracle_tls();
    check_owner_without_tail(); check_native_replay(); check_oracle_failure(false); check_oracle_failure(true);
    check_real_core_oracle_failure(false); check_real_core_oracle_failure(true);
    check_center_identity(); check_center_perturbed_prediction(); check_center_equality_only();
    check_center_tiny_ratio(); check_center_budget_transaction(); check_center_disabled_scope();
    require(details.size() == static_cast<std::size_t>(wrapper_cases + mapping_cases + transaction_cases +
        budget_cases + exception_cases) && component_ipm_calls > 0 && synthetic_core_calls > 0,
        "实际小例与合成边界计数必须守恒且不能冒称零全部求解");
    std::printf("{\"passed\":true,\"public_lp_runs\":0,\"explicit_highs_lp_solve_calls\":0,"
        "\"scope\":\"仅组件自测；component_ipm_calls计harness进入真实solve_ipm或v90_core的API次数(含零预算入口)，不含内部调用拦截；synthetic_core_calls另计，不是公开LP成绩\","
        "\"cases\":%zu,\"wrapper_cases\":%d,\"mapping_cases\":%d,\"transaction_cases\":%d,"
        "\"budget_cases\":%d,\"exception_cases\":%d,\"component_ipm_calls\":%d,\"synthetic_core_calls\":%d,\"details\":[",
        details.size(), wrapper_cases, mapping_cases, transaction_cases, budget_cases, exception_cases,
        component_ipm_calls, synthetic_core_calls);
    for (std::size_t i = 0; i < details.size(); ++i) {
      if (i) std::printf(",");
      std::printf("{\"id\":\"%s\",\"group\":\"%s\"}", details[i].id, details[i].group);
    }
    std::printf("]}\n");
    return 0;
  } catch (const std::exception& error) {
    std::fprintf(stderr, "组件自测失败（已完成%zu组，真实入口%d，合成入口%d）：%s\n",
        details.size(), component_ipm_calls, synthetic_core_calls, error.what());
    return 1;
  }
}

